mapper.select:
select * from employee_schedule where DATE_FORMAT(work_date,'%Y-%m-%d') =
DATE_FORMAT(#{workDate},'%Y-%m-%d')
and employee_id = #{employeeId}

select es.employee_id,es.clinic_id,es.work_date,es.schedule_id,bs.type from employee_schedule es
left join base_schedule bs on es.schedule_id = bs.id
where
es.work_date >= #{startDate} and es.work_date <= #{endDate} and es.employee_id = #{employeeId}

  and es.clinic_id = #{clinicId}

order by es.work_date

select bs.name, bs.type, es.work_date as workDate, bs.first_start_time as firstStartTime, bs.first_end_time as firstEndTime, bs.second_start_time as secondStartTime, bs.second_end_time as secondEndTime, bs.inservice from base_schedule bs left join employee_schedule es on bs.id=es.schedule_id where es.inservice = 1 and bs.inservice and type='休息'
and es.user_id = #{userId}
and DATE_FORMATE(es.work_date,'%y-%m-%d') between DATE_FORMATE(#{startDate},'%y-%m-%d') and DATE_FORMATE(#{endDate},'%y-%m-%d')

select es.id, es.employee_id, es.clinic_id, es.work_date, es.schedule_id, from employee_schedule es where es.inservice = 1
and es.id in
